import java.util.*;

/*
We have 8 triangular faces of an octahedron, each face colored.
Two colorings are considered the same if one can be rotated to the other.

For each test case, given counts of panels of each color, we must count
how many distinct octahedra can be formed.

Burnside's Lemma over the rotation group of the octahedron (24 rotations):

Rotation types and fixed-coloring conditions on the 8 faces:
1) Identity: 1 element, cycles on faces = 8 -> fixes all colorings.
2) 90/270 deg around opposite vertices: 6 elements, two 4-cycles.
   Fixed iff all counts are multiples of 4. Number of fixed colorings:
   choose which two colors occupy the two 4-cycles.
3) 180 deg around opposite vertices: 3 elements, four 2-cycles.
   Fixed iff all counts are even. Number of fixed colorings:
   assign colors to 4 identical-position pairs.
4) 180 deg around opposite edges: 6 elements, two 2-cycles + four 1-cycles.
   Fixed iff after assigning some colors to the two 2-cycles, remaining counts fit the 4 singletons.
5) 120/240 deg around opposite faces: 8 elements, one 1-cycle + one 1-cycle + two 3-cycles.
   Fixed iff after assigning colors to the 3-cycles, remaining counts fit the two singletons.

Then answer = (sum of fixed colorings over 24 rotations) / 24.

Input format:
The classic version of this problem gives:
t
n c1 c2 ... cn
for each case, where n is number of colors and ci are counts summing to 8.

Output:
"Case X: Y"

This solution supports that format.
*/

public class Main {
    static long fact(int n) {
        long r = 1;
        for (int i = 2; i <= n; i++) r *= i;
        return r;
    }

    // multinomial for distributing labeled cycle-slots among colors:
    // total slots m, counts a[i], sum=a
    static long multinomial(int m, int[] a) {
        long res = fact(m);
        for (int x : a) res /= fact(x);
        return res;
    }

    // Identity: number of face colorings with given counts
    static long fixIdentity(int[] c) {
        return fact(8) / denom(c);
    }

    static long denom(int[] c) {
        long d = 1;
        for (int x : c) d *= fact(x);
        return d;
    }

    // 90/270 around vertices: two 4-cycles
    static long fixV90(int[] c) {
        for (int x : c) if (x % 4 != 0) return 0;
        int[] a = new int[c.length];
        int sum = 0;
        for (int i = 0; i < c.length; i++) {
            a[i] = c[i] / 4;
            sum += a[i];
        }
        if (sum != 2) return 0;
        return multinomial(2, a);
    }

    // 180 around vertices: four 2-cycles
    static long fixV180(int[] c) {
        for (int x : c) if (x % 2 != 0) return 0;
        int[] a = new int[c.length];
        int sum = 0;
        for (int i = 0; i < c.length; i++) {
            a[i] = c[i] / 2;
            sum += a[i];
        }
        if (sum != 4) return 0;
        return multinomial(4, a);
    }

    // 180 around edges: two 2-cycles + four 1-cycles
    static long fixE180(int[] c) {
        int n = c.length;
        long ans = 0;

        // choose how many 2-cycles each color occupies: di, sum di = 2, and 2*di <= c[i]
        for (int i = 0; i < n; i++) {
            // one color gets both 2-cycles
            if (c[i] >= 4) {
                int[] rem = c.clone();
                rem[i] -= 4;
                if (sum(rem) == 4) {
                    ans += countSingletonAssignments(rem); // two 2-cycles identical slots among themselves? No, positional slots distinct under fixed rotation cycles
                }
            }
            for (int j = i + 1; j < n; j++) {
                if (c[i] >= 2 && c[j] >= 2) {
                    int[] rem = c.clone();
                    rem[i] -= 2;
                    rem[j] -= 2;
                    if (sum(rem) == 4) {
                        // assign colors i,j to the two distinct 2-cycles: 2! ways if i!=j
                        ans += 2L * countSingletonAssignments(rem);
                    }
                }
            }
        }
        return ans;
    }

    // 120/240 around faces: two 3-cycles + two 1-cycles
    static long fixF120(int[] c) {
        int n = c.length;
        long ans = 0;

        // assign colors to the two 3-cycles
        for (int i = 0; i < n; i++) {
            if (c[i] >= 6) {
                int[] rem = c.clone();
                rem[i] -= 6;
                if (sum(rem) == 2) {
                    ans += countTwoSingletons(rem); // same color on both 3-cycles
                }
            }
            for (int j = i + 1; j < n; j++) {
                if (c[i] >= 3 && c[j] >= 3) {
                    int[] rem = c.clone();
                    rem[i] -= 3;
                    rem[j] -= 3;
                    if (sum(rem) == 2) {
                        // assign i,j to the two distinct 3-cycles
                        ans += 2L * countTwoSingletons(rem);
                    }
                }
            }
        }
        return ans;
    }

    // number of assignments of 4 distinct singleton positions with counts rem summing to 4
    static long countSingletonAssignments(int[] rem) {
        return fact(4) / denom(rem);
    }

    // number of assignments of 2 distinct singleton positions with counts rem summing to 2
    static long countTwoSingletons(int[] rem) {
        return fact(2) / denom(rem);
    }

    static int sum(int[] a) {
        int s = 0;
        for (int x : a) s += x;
        return s;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;
        int T = Integer.parseInt(first);
        StringBuilder out = new StringBuilder();

        for (int tc = 1; tc <= T; tc++) {
            int n = fs.nextInt();
            int[] c = new int[n];
            int total = 0;
            for (int i = 0; i < n; i++) {
                c[i] = fs.nextInt();
                total += c[i];
            }

            long fixed =
                    1L * fixIdentity(c) +
                    6L * fixV90(c) +
                    3L * fixV180(c) +
                    6L * fixE180(c) +
                    8L * fixF120(c);

            long ans = fixed / 24L;

            out.append("Case ").append(tc).append(": ").append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

